UPDATE phone_verifications
SET attempt_count = attempt_count + 1,
    status = CASE
        WHEN attempt_count + 1 >= #{maxAttempts}
            THEN 'LOCKED'
        ELSE status
    END,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND status = 'PENDING'

UPDATE phone_verifications
SET status = 'EXPIRED',
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND status = 'PENDING'

UPDATE phone_verifications
SET status = 'VERIFIED',
    verified_at = #{verifiedAt},
    updated_at = #{verifiedAt}
WHERE id = #{id}
  AND status = 'PENDING'
